// migrate.js
// Database migration script to read SQL files from ./migrations/ directory
// and log each filename in order.

const fs = require('fs');
const path = require('path');

// Path to the migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

// Function to read and list migration files
function listMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log(`Migrations directory not found: ${migrationsDir}`);
    return;
  }

  // Read the migrations directory
  fs.readdir(migrationsDir, (err, files) => {
    if (err) {
      console.error('Error reading migrations directory:', err);
      return;
    }

    // Filter SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in the directory.');
      return;
    }

    // Log each filename in order
    console.log('Migration files to apply in order:');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
  });
}

// Execute the function
listMigrationFiles();

