/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// Read environment variables from .env.test
const envPath = path.resolve(__dirname, '.env.test');
let envVars = {};

if (fs.existsSync(envPath)) {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    lines.forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) {
            const [key, value] = line.split('=', 2);
            if (key && value !== undefined) {
                envVars[key] = value.replace(/^['\"]|['\"]$/g, '');
            }
        }
    });
} else {
    console.error('Error: .env.test file not found');
    process.exit(1);
}

// Set envVars as process.env for consistency
Object.assign(process.env, envVars);

