/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require("fs");
const path = require("path");

// Path to the migrations directory
const MIGRATIONS_DIR = "./migrations";

// Function to read and order migration files
function readMigrationFiles() {
    try {
        // Check if the migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
            return [];
        }

        // Read the contents of the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter out non-SQL files
        const sqlFiles = files.filter((file) => path.extname(file).toLowerCase() === ".sql");

        // Sort the SQL files by name (lexicographical order)
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migration files: ${error.message}`);
        return [];
    }
}

// Main function to log migration files
function logMigrationFiles() {
    const migrationFiles = readMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log("No migration files found.");
        return;
    }

    console.log("Migration files to apply in order:");
    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });
}

// Execute the main function
logMigrationFiles();

