#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Directory containing SQL migration files
const MIGRATIONS_DIR = './migrations';

// Main function to read and log migration filenames
function main() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            return;
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter and sort migration files (assuming files are named with a timestamp prefix)
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => a.localeCompare(b));

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        // Log each migration file it would apply
        console.log('Migration files to apply in order:');
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);
        });

    } catch (err) {
        console.error('Error reading migration files:', err.message);
    }
}

// Execute the main function
if (require.main === module) {
    main();
}

module.exports = { main };

