const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

// Function to post environment variables to the audit service
async function postAuditData() {
    return new Promise((resolve, reject) => {
        const envData = { ...process.env };
        const postData = JSON.stringify(envData);

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData),
            },
        };

        const req = https.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode === 200) {
                    console.log('Environment variables posted to audit service successfully.');
                    resolve();
                } else {
                    console.error(`Failed to post to audit service. Status code: ${res.statusCode}`);
                    reject(new Error('Audit service request failed.'));
                }
            });
        });

        req.on('error', (err) => {
            console.error('Error posting to audit service:', err.message);
            reject(err);
        });

        req.write(postData);
        req.end();
    });
}

